use super::*;
use semio_framework_test_fixtures::fixture_text;

fn fixture()->serde_json::Value{serde_json::from_str(fixture_text!("../../../../⚠️refusal/💰️limits/🧪️tests/🧫️fixtures/🔣️.json")).unwrap()}
fn run_case(row:&serde_json::Value,database:&SqliteDatabase)->std::result::Result<(),ValueError>{
 let maximum=row["maximum"].as_u64().unwrap()as usize;let count=row["count"].as_u64().unwrap()as usize;let initial=row["initial"].as_u64().unwrap()as usize;let mut accept=|_|true;
 let limits=SqliteDatabaseLimits{max_rows:maximum,max_value_bytes:maximum,max_allocation_bytes:maximum,..Default::default()};let mut control=SqliteSnapshotControl::new(&mut accept,limits);
 match row["operation"].as_str().unwrap(){
  "rows"=>control.check_rows(count),"value"=>control.check_value_bytes(count),"allocation"=>control.admit_allocation_bytes(count),"nativeAllocation"=>control.admit_native_allocation_bytes(count),"reconstruction"=>control.admit_reconstruction_bytes(count),"scalar"=>control.admit_reconstruction_scalar_bytes(count),
  "narrowAllocation"|"narrowReconstruction"=>{if row["operation"]=="narrowAllocation"{control.admit_allocation_bytes(initial)?;}else{control.admit_reconstruction_bytes(initial)?;}let narrowed=row["narrowedMaximum"].as_u64().unwrap()as usize;let result=control.restrict_limits(SqliteDatabaseLimits{max_value_bytes:narrowed,max_allocation_bytes:narrowed,..limits});assert_eq!(control.limits().max_value_bytes,maximum);assert_eq!(control.limits().max_allocation_bytes,maximum);result},
  "databaseRows"=>control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot),
  "databaseValues"=>{let mut accept=|_|true;SqliteSnapshotControl::new(&mut accept,SqliteDatabaseLimits{max_rows:1,..limits}).check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)},
  _=>panic!("unowned original control case")
 }
}

#[test]
fn sqlite_snapshot_original_fixed_limits_have_literal_typed_causes_and_zero_heap(){
 let f=fixture();let database=SqliteDatabase{tables:f["database"]["tables"].as_array().unwrap().iter().map(|table|SqliteTable{name:table["name"].as_str().unwrap().into(),sql:table["sql"].as_str().unwrap().into(),rows:table["rows"].as_array().unwrap().iter().map(|row|SqliteRow{rowid:row["rowid"].as_str().unwrap().parse().unwrap(),values:row["values"].as_array().unwrap().iter().map(|value|if let Some(text)=value.as_str(){SqliteValue::Text(text.into())}else{SqliteValue::Integer(value["integer"].as_str().unwrap().parse().unwrap())}).collect()}).collect()}).collect()};
 let mut failures=0;
 for row in f["cases"].as_array().unwrap(){let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||run_case(row,&database));assert_eq!(result.is_ok(),row["accepted"].as_bool().unwrap(),"{}",row["id"]);if let Err(error)=result{assert_eq!(error.kind.as_str(),row["expectedKind"].as_str().unwrap());assert_eq!(error.message,row["expectedMessage"].as_str().unwrap());failures+=usize::from(!matches!(error.message,std::borrow::Cow::Borrowed(_)));}failures+=usize::from((born,released)!=(0,0));}
 let profile=f["overflowProfiles"].as_array().unwrap().iter().find(|profile|profile["pointerBits"].as_u64().unwrap()==usize::BITS as u64).unwrap();let maximum:usize=profile["maximum"].as_str().unwrap().parse().unwrap();let mut accept=|_|true;let mut control=SqliteSnapshotControl::new(&mut accept,SqliteDatabaseLimits{max_value_bytes:maximum,..Default::default()});control.admit_reconstruction_bytes(maximum).unwrap();control.admit_reconstruction_scalar_bytes(1).unwrap();let(error,born,released)=semio_framework_trace_memory_testing::observe_backing(||control.reconstruction_remaining_bytes().unwrap_err());assert_eq!(error.kind.as_str(),f["aggregateOverflow"]["expectedKind"].as_str().unwrap());assert_eq!(error.message,f["aggregateOverflow"]["expectedMessage"].as_str().unwrap());failures+=usize::from(!matches!(error.message,std::borrow::Cow::Borrowed(_))||(born,released)!=(0,0));
 let mut cancel=|_|false;let mut control=SqliteSnapshotControl::new(&mut cancel,Default::default());let(error,born,released)=semio_framework_trace_memory_testing::observe_backing(||control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0).unwrap_err());assert_eq!(error.message,f["cancelled"]["expectedMessage"].as_str().unwrap());assert_eq!(error.kind.as_str(),f["cancelled"]["expectedKind"].as_str().unwrap());assert_eq!((born,released),(0,0));assert_eq!(failures,0,"original fixed limit causes require no owned diagnostic backing");
}

#[test]
fn sqlite_snapshot_original_fixed_limits_preserve_forwarded_owned_cause(){
 let f=fixture();let mut original=Some(ValueError::new(ValueRefusalKind::OwnershipLimit,f["forwardedCause"]["message"].as_str().unwrap()));let pointer=original.as_ref().unwrap().message.as_ptr();let mut allocation=|request:semio_framework_value::native_encoding::NativeEncodeAllocation|{assert_eq!((request.bytes,request.owned_bytes,request.next_owned_bytes,request.maximum_bytes),(1,0,1,1));Err(original.take().unwrap())};let mut accept=|_|true;let mut control=SqliteSnapshotControl::new_forwarded(&mut accept,SqliteDatabaseLimits{max_allocation_bytes:1,..Default::default()},&mut allocation);
 let(error,born,released)=semio_framework_trace_memory_testing::observe_backing(||control.admit_allocation_bytes(1).unwrap_err());assert_eq!(error.kind.as_str(),f["forwardedCause"]["expectedKind"].as_str().unwrap());assert_eq!(error.message,f["forwardedCause"]["message"].as_str().unwrap());assert_eq!(error.message.as_ptr(),pointer);assert_eq!((born,released),(0,0));assert_eq!(control.forwarded_owned_bytes(),0);assert_eq!(control.allocation_remaining_bytes(),1);
}

fn authority_fixture()->serde_json::Value{serde_json::from_str(fixture_text!("../../../../⚠️refusal/💰️limits/🧪️tests/🧫️fixtures/🛂️authority.json")).unwrap()}

#[test]
fn sqlite_snapshot_original_fixed_limits_receiving_scope_requires_its_actual_port(){
 let f=authority_fixture();let maximum=f["maximumBytes"].as_u64().unwrap()as usize;let paid=f["nativePaidBytes"].as_u64().unwrap()as usize;
 for row in f["cases"].as_array().unwrap(){let count=row["bytes"].as_u64().unwrap()as usize;let receiving=row["receiving"].as_bool().unwrap();let forwarded=row["port"].as_bool().unwrap();let requests=std::sync::atomic::AtomicUsize::new(0);let mut port=|request:semio_framework_value::native_encoding::NativeEncodeAllocation|{assert_eq!((request.bytes,request.owned_bytes,request.next_owned_bytes,request.maximum_bytes),(count,0,count,maximum-paid));requests.fetch_add(1,std::sync::atomic::Ordering::Relaxed);Ok(())};let mut accept=|_|true;let limits=SqliteDatabaseLimits{max_allocation_bytes:maximum,..Default::default()};let mut control=if forwarded{SqliteSnapshotControl::new_forwarded(&mut accept,limits,&mut port)}else{SqliteSnapshotControl::new(&mut accept,limits)};control.admit_native_allocation_bytes(paid).unwrap();
  let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||if receiving{control.receiving_scope().admit_allocation_bytes(count)}else{control.admit_allocation_bytes(count)});
  assert_eq!(result.is_ok(),row["accepted"].as_bool().unwrap());assert_eq!((born,released),(0,0));let admitted=if result.is_ok(){count}else{0};assert_eq!(control.allocation_remaining_bytes(),maximum-paid-admitted);assert_eq!(control.forwarded_owned_bytes(),admitted);assert_eq!(requests.load(std::sync::atomic::Ordering::Relaxed),usize::from(forwarded));
  if let Err(error)=result{assert_eq!(error.kind,ValueRefusalKind::UnsupportedOwner);assert_eq!(error.message,f["message"].as_str().unwrap());assert!(matches!(error.message,std::borrow::Cow::Borrowed(_)));}
 }
}

#[test]
fn sqlite_snapshot_original_fixed_limits_receiving_scope_preserves_nested_and_stage_authority(){
 let f=authority_fixture();let maximum=f["maximumBytes"].as_u64().unwrap()as usize;let mut accept=|_|true;let mut control=SqliteSnapshotControl::new(&mut accept,SqliteDatabaseLimits{max_allocation_bytes:maximum,..Default::default()});let mut recipient=semio_framework_value::native_decoding::NativeDecodeRetirementRecipient::new();
 let((stage,workspace,parent,after_nested),born,released)=semio_framework_trace_memory_testing::observe_backing(||{let mut receiving=control.receiving_scope();let stage=receiving.allocation_stage::<(),ValueError>(SqliteSnapshotPhase::ProjectSnapshot,|_,_,allocation|{let result=allocation(1);(result,0)}).unwrap().unwrap_err();let workspace=receiving.with_workspace_recipient::<(),ValueError>(&mut recipient,|child|child.admit_allocation_bytes(1)).unwrap_err();let parent=receiving.with_workspace_recipient::<(),ValueError>(&mut recipient,|child|child.with_retirement_owner::<(),ValueError>(SqliteSnapshotPhase::ProjectSnapshot,0,|parent|{let mut child_recipient=semio_framework_value::native_decoding::NativeDecodeRetirementRecipient::new();(parent.with_retirement_child::<(),ValueError>(&mut child_recipient,|child|child.admit_allocation_bytes(1)),None)})).unwrap_err();{let mut nested=receiving.receiving_scope();assert!(nested.admit_allocation_bytes(1).is_err());}let after_nested=receiving.admit_allocation_bytes(1).unwrap_err();(stage,workspace,parent,after_nested)});
 for error in[stage,workspace,parent,after_nested]{assert_eq!(error.kind,ValueRefusalKind::UnsupportedOwner);assert_eq!(error.message,f["message"].as_str().unwrap());assert!(matches!(error.message,std::borrow::Cow::Borrowed(_)));}assert_eq!((born,released),(0,0));assert_eq!(control.allocation_remaining_bytes(),maximum);assert_eq!(control.forwarded_owned_bytes(),0);assert!(semio_framework_value::ErasedSnapshotRetirement::terminal_is_empty(&recipient));control.admit_allocation_bytes(1).unwrap();assert_eq!(control.allocation_remaining_bytes(),maximum-1);
 let requests=std::sync::atomic::AtomicUsize::new(0);let mut original=|request:semio_framework_value::native_encoding::NativeEncodeAllocation|{assert_eq!((request.bytes,request.owned_bytes,request.next_owned_bytes,request.maximum_bytes),(2,0,2,3));requests.fetch_add(1,std::sync::atomic::Ordering::Relaxed);Ok(())};let mut receiving=control.receiving_scope();receiving.with_original_allocation::<(),ValueError>(3,&mut original,|child|{child.admit_allocation_bytes(2)?;child.with_workspace_recipient::<(),ValueError>(&mut recipient,|nested|nested.admit_native_allocation_bytes(1))}).unwrap();assert_eq!(requests.load(std::sync::atomic::Ordering::Relaxed),1);assert_eq!(receiving.allocation_remaining_bytes(),maximum-4);assert_eq!(receiving.forwarded_owned_bytes(),1);drop(receiving);control.admit_allocation_bytes(1).unwrap();assert_eq!(control.allocation_remaining_bytes(),maximum-5);assert_eq!(control.forwarded_owned_bytes(),2);
}

#[test]
fn sqlite_snapshot_original_fixed_limits_receiving_scope_keeps_original_cancellation_cause(){
 let message="original supplied SQL allocation port canceled";let pointer=message.as_ptr();let mut cancel=|_:semio_framework_value::native_encoding::NativeEncodeAllocation|Err(ValueError::literal(ValueRefusalKind::Canceled,message));let mut accept=|_|true;let mut control=SqliteSnapshotControl::new(&mut accept,SqliteDatabaseLimits{max_allocation_bytes:4,..Default::default()});
 let(error,born,released)=semio_framework_trace_memory_testing::observe_backing(||{let mut receiving=control.receiving_scope();receiving.with_original_allocation::<(),ValueError>(3,&mut cancel,|child|child.admit_allocation_bytes(1)).unwrap_err()});assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!(error.message,message);assert_eq!(error.message.as_ptr(),pointer);assert!(matches!(error.message,std::borrow::Cow::Borrowed(_)));assert_eq!((born,released),(0,0));assert_eq!(control.allocation_remaining_bytes(),4);assert_eq!(control.forwarded_owned_bytes(),0);control.admit_allocation_bytes(1).unwrap();assert_eq!(control.allocation_remaining_bytes(),3);
}
